const defaultBreakpoints: Breakpoints = { xs: 0, sm: 400, md: 768, lg: 1024, xl: 1280 };

export function useBreakpoint<T extends Breakpoints>(
  customBreakpoints?: T,
  initialWidth = Infinity,
  initialHeight = Infinity,
