    `%c${name || 'RenderCount'}: %c${count.current}`,
    'font-size: 14px;  font-weight: bold;',
    'color: #999; font-size: 14px;',
  );

  return count.current;
}
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { canUseDOM, isString, off, on } from './utils';

interface UseScriptOptions {
  async?: boolean;
  defer?: boolean;
  id?: string;
  type?: string;
}

export type UseScriptResult = [loaded: boolean, error: boolean];

export function useScript(
  src: string,
  idOrOptions: string | UseScriptOptions = {},
): [loaded: boolean, error: boolean] {
  const options = useMemo(
    () => (isString(idOrOptions) ? { id: idOrOptions } : idOrOptions),
    [idOrOptions],
  );
  const script = useRef<HTMLScriptElement>(null);
  const [state, setState] = useState({
    loaded: false,
    error: false,
  });

  const onLoad = useCallback(() => {
    setState({
      loaded: true,
      error: false,
    });
  }, []);

  const onError = useCallback(() => {
    if (script.current) {
      script.current.remove();
    }

    setState({
      loaded: false,
      error: true,
    });
  }, []);

  useEffect(
    () => {
      if (!canUseDOM() || script.current) {
        return undefined;
      }

      const element = document.createElement('script');

      element.async = options.async ?? true;
      element.defer = options.defer ?? false;
      element.type = options.type || 'text/javascript';
      element.id = options.id || src;
      element.src = src;

      script.current = element;

      const { current } = script;

      on(current, 'load', onLoad);
      on(current, 'error', onError);

      // Add script to document body
      document.body.appendChild(current);

      return () => {
        off(current, 'load', onLoad);
        off(current, 'error', onError);
      };
    },
    [onError, onLoad, options, src], // Only re-run effect if script src changes
  );

  return [state.loaded, state.error];
}
import { useEffect, useRef, useState } from 'react';

import { useUnmount } from './useUnmount';

export function useThrottle<T extends (...arguments_: Array<any>) => void>(
  callback: T,
  delayMs = 500,
  trailing: boolean = false,
): () => void {
  const [now, setNow] = useState(0);
  const callbackRef = useRef(callback);
  const hasPendingCall = useRef(false);
  const timer = useRef<number>(undefined);

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  useEffect(() => {
    if (!now) {
      return;
    }

    if (!timer.current) {
      callbackRef.current();

      const timerCallback = () => {
        if (hasPendingCall.current) {
          hasPendingCall.current = false;

          if (trailing) {
            callbackRef.current();
          }

          timer.current = undefined;
        } else {
          timer.current = undefined;
        }
      };

      timer.current = window.setTimeout(timerCallback, delayMs);
    } else {
      hasPendingCall.current = true;
    }
  }, [delayMs, now, trailing]);

  useUnmount(() => {
    window.clearTimeout(timer.current);
    timer.current = undefined;
  });

  return () => setNow(Date.now());
}
