    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}
import { useEffect, useRef, useState } from 'react';

import { useUnmount } from './useUnmount';

export function useThrottleValue<T>(value: T, delayMs: number): T {
  const [throttledValue, setThrottledValue] = useState<T>(value);
  const hasNextValue = useRef(false);
  const nextValue = useRef<any>(null);
  const timer = useRef<number>(undefined);

  useEffect(() => {
    if (!timer.current) {
      setThrottledValue(value);

      const timeoutCallback = () => {
        if (hasNextValue.current) {
          hasNextValue.current = false;
          setThrottledValue(nextValue.current);
          timer.current = window.setTimeout(timeoutCallback, delayMs);
        } else {
          timer.current = undefined;
        }
      };

      timer.current = window.setTimeout(timeoutCallback, delayMs);
    } else {
      hasNextValue.current = true;
      nextValue.current = value;
    }
  }, [delayMs, value]);

  useUnmount(() => {
    window.clearTimeout(timer.current);
    timer.current = undefined;
  });

  return throttledValue;
}
import { useCallback, useEffect, useRef } from 'react';

import { TimerStatus } from './types';

export type UseTimeoutStatus = TimerStatus;

export interface UseTimeoutResult {
  cancel: () => void;
  getStatus: () => UseTimeoutStatus;
  reset: () => void;
}

export function useTimeout(callback: () => void, delayMs: number = 0): UseTimeoutResult {
  const status = useRef<UseTimeoutStatus>('pending');
  const timeout = useRef<ReturnType<typeof setTimeout>>(null);
  const savedCallback = useRef(callback);

  const clear = useCallback(() => {
    status.current = 'cancelled';
    timeout.current && clearTimeout(timeout.current);
  }, []);

  const set = useCallback(() => {
    status.current = 'pending';
    timeout.current && clearTimeout(timeout.current);

    timeout.current = setTimeout(() => {
      status.current = 'completed';
      savedCallback.current();
    }, delayMs);
  }, [delayMs]);

  const getStatus = useCallback(() => status.current, []);

  // update ref when function changes
  useEffect(() => {
    savedCallback.current = callback;
  }, [callback]);

  // set on mount, clear on unmount
  useEffect(() => {
    set();

    return clear;
  }, [set, clear]);

  return { cancel: clear, getStatus, reset: set };
}
import { ActionDispatch, AnyActionArg, useCallback, useReducer } from 'react';

export type UseToggleResult = [
  value: boolean,
  actions: {
    toggle: ActionDispatch<AnyActionArg>;
    toggleOff: () => void;
    toggleOn: () => void;
  },
];

export function useToggle(initialValue: boolean = true): UseToggleResult {
  const [value, toggle] = useReducer(
    (state: boolean, nextValue?: boolean) => (typeof nextValue === 'boolean' ? nextValue : !state),
    initialValue,
  );

  const toggleOn = useCallback(() => toggle(true), []);
  const toggleOff = useCallback(() => toggle(false), []);

  return [value, { toggle, toggleOn, toggleOff }];
}
